def transform(grid):
    """Reduce each 3x3 cell block to its most frequent non-background color."""
    out = []
    for block_r in range(0, len(grid), 3):
        row = []
        for block_c in range(0, len(grid[0]), 3):
            counts = Counter(
                grid[r][c]
                for r in range(block_r, min(block_r + 3, len(grid)))
                for c in range(block_c, min(block_c + 3, len(grid[0])))
                if grid[r][c] != 5
            )
            row.append(counts.most_common(1)[0][0] if counts else 5)
        out.append(row)
